interface Generic<T> {
    y(x: T[]): void;
    y(x: T): void;
}

// Merges signatures when type parameters are the same.
function f6<T extends number>(x: T[]): void;
function f6<T extends number>(x: T): void;
function f6(x: unknown): void {}

// Supports abstract methods.
abstract class Foo {
